"use client";

import { Heading, HeadingProps } from "@chakra-ui/react";
import { forwardRef } from "react";

export interface BaseHeadingProps extends HeadingProps {
  /**
   * Size variant from your heading recipe (xs → 7xl)
   */
  size?:
    | "xs"
    | "sm"
    | "md"
    | "lg"
    | "xl"
    | "2xl"
    | "3xl"
    | "4xl"
    | "5xl"
    | "6xl"
    | "7xl";
}

/**
 * BaseHeading wraps Chakra's <Heading> and automatically
 * maps `size` → textStyle, so you can pass any size variant.
 */
export const BaseHeading = forwardRef<HTMLHeadingElement, BaseHeadingProps>(
  ({ as = "h1", size = "xl", ...props }, ref) => {
    return <Heading ref={ref} as={as} textStyle={size} {...props} />;
  }
);

BaseHeading.displayName = "BaseHeading";
