"use client";
import React from "react";
import { BaseIconButton, BaseIconButtonProps } from "./BaseIconButton";
import { BaseButton, BaseButtonProps } from "./BaseButton";

export function createLockedButton(
  variant: BaseButtonProps["variant"],
  size: BaseButtonProps["size"]
) {
  type LockedProps = Omit<
    BaseButtonProps,
    | "variant"
    | "size"
    | "bg"
    | "background"
    | "backgroundColor"
    | "color"
    | "border"
    | "borderColor"
    | "borderWidth"
    | "borderRadius"
    | "padding"
    | "height"
    | "width"
    | "p"
    | "px"
    | "py"
    | "pt"
    | "pb"
    | "pl"
    | "pr"
    | "fontSize"
    | "fontWeight"
    | "lineHeight"
    | "letterSpacing"
    | "textTransform"
    | "boxShadow"
    | "shadow"
    | "_hover"
  >;

  return (
    props: LockedProps & {
      bg?: any;
      background?: any;
      backgroundColor?: any;
      color?: any;
      border?: any;
      borderColor?: any;
      borderWidth?: any;
      borderRadius?: any;
      padding?: any;
      height?: any;
      width?: any;
      p?: any;
      px?: any;
      py?: any;
      pt?: any;
      pb?: any;
      pl?: any;
      pr?: any;
      fontSize?: any;
      fontWeight?: any;
      lineHeight?: any;
      letterSpacing?: any;
      textTransform?: any;
      boxShadow?: any;
      shadow?: any;
      _hover?: any;
    }
  ) => {
    const {
      bg,
      background,
      backgroundColor,
      color,
      border,
      borderColor,
      borderWidth,
      borderRadius,
      padding,
      height,
      width,
      p,
      px,
      py,
      pt,
      pb,
      pl,
      pr,
      fontSize,
      fontWeight,
      lineHeight,
      letterSpacing,
      textTransform,
      boxShadow,
      shadow,
      _hover,
      ...restProps
    } = props;
    return <BaseButton {...restProps} variant={variant} size={size} />;
  };
}

export function createLabeledButton(
  label: string,
  variant: BaseButtonProps["variant"] = "solid",
  size: BaseButtonProps["size"] = "md",
  useSpecificWidth: boolean = true
) {
  const LockedBase = createLockedButton(variant, size);

  const LabeledButton: React.FC<
    Omit<BaseButtonProps, "children" | "variant" | "size">
  > = (props) => (
    <LockedBase {...props} w={useSpecificWidth ? "btn-w-specific" : undefined}>
      {label}
    </LockedBase>
  );

  LabeledButton.displayName = `${label.replace(/\s+/g, "")}Button`;
  return LabeledButton;
}

export function createFlexButton(
  variant: BaseButtonProps["variant"],
  size: BaseButtonProps["size"],
  label?: string,
  leftIcon?: React.ReactNode
) {
  const LockedBase = createLockedButton(variant, size);

  const FlexButton: React.FC<Omit<BaseButtonProps, "variant" | "size">> = (
    props
  ) => (
    <LockedBase
      {...props}
      leftIcon={leftIcon}
      display="flex"
      justifyContent="center"
      alignItems="center"
      w="100%"
    >
      {props.children || label}
    </LockedBase>
  );

  FlexButton.displayName = `${label?.replace(/\s+/g, "") || "Flex"}Button`;
  return FlexButton;
}

export function createLockedIconButton(
  variant: BaseIconButtonProps["variant"],
  size: BaseIconButtonProps["size"]
) {
  type LockedProps = Omit<
    BaseIconButtonProps,
    | "variant"
    | "size"
    | "bg"
    | "background"
    | "backgroundColor"
    | "color"
    | "border"
    | "borderColor"
    | "borderWidth"
    | "padding"
    | "fontSize"
    | "_hover"
    | "p"
    | "px"
    | "py"
    | "pt"
    | "pb"
    | "pl"
    | "pr"
  >;

  return (props: LockedProps) => (
    <BaseIconButton {...props} variant={variant} size={size} />
  );
}

export function createStaticIconButton(
  Icon: React.ReactElement,
  variant: BaseIconButtonProps["variant"],
  size: BaseIconButtonProps["size"],
  ariaLabel: string
) {
  const LockedIconButton = createLockedIconButton(variant, size);

  const StaticIconButton: React.FC<
    Omit<BaseIconButtonProps, "variant" | "size" | "children" | "rounded">
  > = (props) => (
    <LockedIconButton {...props} rounded="full" aria-label={ariaLabel}>
      {Icon}
    </LockedIconButton>
  );

  StaticIconButton.displayName = `${ariaLabel.replace(/\s+/g, "")}IconButton`;

  return StaticIconButton;
}
