"use client";

import { Text, TextProps } from "@chakra-ui/react";
import { forwardRef } from "react";

export interface BaseTextProps extends TextProps {
  /**
   * Text style key defined in your textStyles config
   */
  textStyle?:
    | "2xs"
    | "xs"
    | "sm"
    | "md"
    | "lg"
    | "xl"
    | "2xl"
    | "3xl"
    | "4xl"
    | "5xl"
    | "6xl"
    | "7xl"
    | "label"
    | "none";
}

/**
 * BaseText wraps Chakra's <Text> and forwards textStyle variants.
 */
export const BaseText = forwardRef<HTMLParagraphElement, BaseTextProps>(
  ({ textStyle = "md", as = "p", ...props }, ref) => {
    return <Text ref={ref} as={as} textStyle={textStyle} {...props} />;
  }
);

BaseText.displayName = "BaseText";
