import { IoSearchOutline } from "react-icons/io5";
import { LuFileChartColumn, LuLogOut } from "react-icons/lu";
import { RiPencilFill } from "react-icons/ri";
import {
  createFlexButton,
  createLabeledButton,
  createStaticIconButton,
} from "./ButtonCreators";

export const GoogleFlexButton = createFlexButton(
  "outline",
  "md",
  "GOOGLE LOGIN",
  <FcGoogle style={{ fontSize: "1.5em" }} />
);

export const LoginFlexButton = createFlexButton("solid", "md", "LOGIN");

// Outline Buttons
export const BackButton = createLabeledButton("BACK", "outline");
export const CancelButton = createLabeledButton("CANCEL", "outline");

// Solid Buttons (primary actions)
export const SaveButton = createLabeledButton("SAVE");
export const ApplyButton = createLabeledButton("APPLY");
export const SendButton = createLabeledButton("SEND");
export const SubmitButton = createLabeledButton("SUBMIT");
export const CreateButton = createLabeledButton("CREATE");
export const ContinueButton = createLabeledButton("CONTINUE");
export const OrderButton = createLabeledButton("ORDER");
export const NextButton = createLabeledButton("NEXT");
export const ConfirmButton = createLabeledButton("CONFIRM");
export const DeleteButton = createLabeledButton("DELETE");
export const LoginButton = createLabeledButton("LOG IN");
export const LogoutButton = createLabeledButton("LOG OUT");
export const SignupButton = createLabeledButton("SIGN UP");
export const ResetButton = createLabeledButton("RESET");

//Icon Static Icons
