
import {
  createSystem,
  defaultConfig,
  defineConfig,
  defineTokens,
} from "@chakra-ui/react";
import { buttonGroupRecipe, buttonRecipe } from "./recipes";
import { textStyles } from "./text-styles";
import { fontSizes, fontWeights, letterSpacings, lineHeights, radii, sizes, spacing } from "./tokens";

export const baseTokens = defineTokens({
  sizes: {
    "btn-h-sm": { value: "32px" }, //2rem
    "btn-h-md": { value: "40px" }, //2.5rem
    "btn-h-lg": { value: "56px" }, //3.5rem
    "btn-h-xl": { value: "56px" }, //3.5rem
    "btn-w-specific": { value: "120px" }, //7.5rem
    "input-h-standard": { value: "48px" }, //3rem 
  },
  borders: {
    "btn-outline-hairline": { value: "1px" },
    "btn-outline-medium": { value: "2px" },
    "btn-outline-thick": { value: "3px" },
  },
  breakpoints: {
    mobile: { value: "320px" },
    tablet: { value: "768px" },
    desktop: { value: "960px" },
  },
  
});


export const colorPalettes = {
  green: {
    primary: "#109448",
    primaryHover: "#006838",
    primaryDisabled: "#92DDBF",
    primaryForeground: "#ffffff",
    background: "#ffffff",
    foreground: "#000000",
    foregroundHover: "#006838",
  },
  pink: {
    primary: "#F686C3",
    primaryHover: "#E13481",
    primaryDisabled: "#FFCEE9",
    primaryForeground: "#ffffff",
    background: "#ffffff",
    foreground: "#000000",
    foregroundHover: "#E13481",
  },
  blue: {
    primary: "#40CFFF",
    primaryHover: "#026BA9",
    primaryDisabled: "#CAF0F8",
    primaryForeground: "#ffffff",
    background: "#ffffff",
    foreground: "#000000",
    foregroundHover: "#a3c8fa",
  },
  orange: {
    primary: "#F4845F",
    primaryHover: "#F1592B",
    primaryDisabled: "#F7B267",
    primaryForeground: "#ffffff",
    background: "#ffffff",
    foreground: "#000000",
    foregroundHover: "#F1592B",
  },
  neutral: {
    primary: "#22223B",
    primaryHover: "#000000",
    primaryDisabled: "#F2E9E4",
    primaryForeground: "#ffffff",
    background: "#ffffff",
    foreground: "#000000",
    foregroundHover: "#22223B",
  },
};

export const createStPeterSystem = (
  themeName: keyof typeof colorPalettes = "neutral",
  font: string = "Montserrat"
) => {
  const colors = colorPalettes[themeName];

  const fallbackFonts = `"${font}", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif`;

  const tokens = defineTokens({
    ...baseTokens,
    fontSizes, 
    fontWeights,
    radii,
    letterSpacings,
    lineHeights,
    spacing,
    sizes,
    fonts: {
      body: { value: fallbackFonts },
      heading: { value: fallbackFonts },
      // mono: {
      //   value: `SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace`,
      // },
    },
  });

  const config = defineConfig({
    theme: {
      tokens,
      textStyles,
      semanticTokens: {
        colors: {
          primary: { value: colors.primary },
          primaryHover: { value: colors.primaryHover },
          primaryDisabled: { value: colors.primaryDisabled },
          primaryForeground: { value: colors.primaryForeground },
          background: { value: colors.background },
          foreground: { value: colors.foreground },
          foregroundHover: { value: colors.foregroundHover },
        },
      },
      recipes: {
        button: buttonRecipe,
      },
      slotRecipes: {
        buttonGroup: buttonGroupRecipe, 
      },
    },
  });

  const system = createSystem(defaultConfig, config);

  return system;
};
