import { defineSlotRecipe } from "@chakra-ui/react";

export const buttonGroupRecipe = defineSlotRecipe({
  className: "stpeter-button-group",

  slots: ["group"],

  base: {
    group: {
      display: "inline-flex",
      alignItems: "center",
      justifyContent: "center",
      gap: "2", 
    },
  },

  variants: {
    size: {
      "2xs": { group: { gap: "1" } },
      xs:    { group: { gap: "1.5" } },
      sm:    { group: { gap: "2" } },
      md:    { group: { gap: "2.5" } },
      lg:    { group: { gap: "3" } },
      xl:    { group: { gap: "3.5" } },
      "2xl": { group: { gap: "4" } },
    },
    variant: {
      solid:  { group: { _child: { borderRadius: "0" } } },
      outline:{ group: { _child: { borderRadius: "0" } } },
      ghost:  { group: { _child: { borderRadius: "0" } } },
    },
    isAttached: {
      true: {
        group: {
          "& > *:first-of-type": { borderRightRadius: "0" },
          "& > *:not(:first-of-type):not(:last-of-type)": {
            borderRadius: "0",
          },
          "& > *:last-of-type": { borderLeftRadius: "0" },
        },
      },
      false: {},
    },
  },
  // 2 sir ron, 2 sir jeff, 3 sir jim, 3 nawawala
  
  defaultVariants: {
    size: "md",
    variant: "solid",
    isAttached: false,
  },
});
