"use client";

import { BaseHeading } from "./BaseHeading";

export const H1: React.FC<React.HTMLAttributes<HTMLElement>> = (props) => (
  <BaseHeading as="h1" size="5xl" {...props} />
);
export const H2: React.FC<React.HTMLAttributes<HTMLElement>> = (props) => (
  <BaseHeading as="h2" size="4xl" {...props} />
);
export const H3: React.FC<React.HTMLAttributes<HTMLElement>> = (props) => (
  <BaseHeading as="h3" size="3xl" {...props} />
);
export const H4: React.FC<React.HTMLAttributes<HTMLElement>> = (props) => (
  <BaseHeading as="h4" size="xl" {...props} />
);
